-- Migración 058: Base de datos de alimentos USDA SR Legacy (curada)
-- Generada automáticamente. 4,608 alimentos con macros por 100g.

CREATE TABLE IF NOT EXISTS alimento (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  fdc_id      integer UNIQUE,
  nombre      text NOT NULL,
  nombre_en   text,
  categoria   text,
  kcal        numeric(8,2),
  proteina_g  numeric(8,2),
  carbs_g     numeric(8,2),
  grasa_g     numeric(8,2),
  fibra_g     numeric(8,2),
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS alimento_porcion (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  alimento_id uuid NOT NULL REFERENCES alimento(id) ON DELETE CASCADE,
  etiqueta    text,
  gramos      numeric(8,2)
);

CREATE INDEX IF NOT EXISTS idx_alimento_nombre ON alimento USING gin(to_tsvector('spanish', nombre));
CREATE INDEX IF NOT EXISTS idx_alimento_categoria ON alimento(categoria);

